"""Text-to-SQL harness: draft query, verify it by execution (errors, empty
results, truncation, and duplicate-row fan-out from one-to-many joins), and
spend the second policy call on a targeted repair turn when a check fails.

Contract (fixed): solve(task, env) -> {"sql": str}
"""

import re

SQL_BLOCK = re.compile(r"```(?:sql|sqlite)?\s*(.*?)```", re.S | re.I)
START_KW = re.compile(r"^\s*(WITH|SELECT)\b", re.I)


def extract_sql(text):
    text = text or ""
    blocks = [b.strip() for b in SQL_BLOCK.findall(text) if b.strip()]
    if blocks:
        return blocks[-1].rstrip(";").strip()
    # Unclosed code fence (truncated generation): take what follows the fence.
    m = re.search(r"```(?:sql|sqlite)?\s*(.*)$", text, re.S | re.I)
    if m and START_KW.match(m.group(1)):
        return m.group(1).strip().rstrip(";").strip()
    # Bare SQL somewhere in the reply.
    m = re.search(r"(?:^|\n)\s*(WITH|SELECT)\b", text, re.I)
    if m:
        return text[m.start():].strip().rstrip(";").strip()
    return text.strip().rstrip(";").strip()


def looks_truncated(sql):
    if not sql:
        return True
    if sql.count("(") != sql.count(")"):
        return True
    if sql.count("'") % 2 == 1 or sql.count('"') % 2 == 1:
        return True
    if re.search(r"\b(SELECT|FROM|WHERE|AND|OR|BY|ON|JOIN|HAVING|LIMIT|AS|IN|LIKE|=|<|>|,)\s*$", sql, re.I):
        return True
    return False


def build_user(task, env):
    user = (
        f"Database: {task['db_id']}\n\nSchema:\n{env.schema(task['db_id'])}"
    )
    desc = ""
    try:
        desc = env.descriptions(task["db_id"]) or ""
    except Exception:
        desc = ""
    if desc.strip():
        user += f"\n\nColumn descriptions:\n{desc.strip()[:4000]}"
    user += f"\n\nQuestion: {task['question']}"
    if task.get("hint"):
        user += f"\nHint: {task['hint']}"
    return user


def _strip_trailing_limit(sql):
    """Remove a trailing LIMIT clause (possibly with OFFSET) outside quotes."""
    depth = 0
    quote = None
    last_kw = None
    i = 0
    n = len(sql)
    while i < n:
        c = sql[i]
        if quote:
            if c == quote:
                quote = None
        elif c in ("'", '"'):
            quote = c
        elif c == "(":
            depth += 1
        elif c == ")":
            depth -= 1
        elif depth == 0 and (c.isalpha() or c == "_"):
            j = i
            while j < n and (sql[j].isalnum() or sql[j] == "_"):
                j += 1
            last_kw = (sql[i:j].upper(), i)
            i = j
            continue
        i += 1
    if last_kw and last_kw[0] == "LIMIT":
        tail = sql[last_kw[1]:]
        if re.fullmatch(r"(?is)LIMIT\s+\d+(\s*,\s*\d+|\s+OFFSET\s+\d+)?\s*", tail):
            return sql[:last_kw[1]].rstrip()
    return sql


def distinct_variant(sql):
    """A DISTINCT-wrapped copy of the query used only as a local duplicate-row
    probe. Returns None when the query shape makes the probe uninformative."""
    s = (sql or "").strip().rstrip(";").strip()
    if not s or ";" in s:
        return None
    if not re.match(r"^SELECT\b", s, re.I):
        return None
    head = s[:200]
    if re.match(r"^SELECT\s+(DISTINCT|ALL)\b", s, re.I):
        return None
    if re.search(r"\b(GROUP\s+BY|UNION|INTERSECT|EXCEPT)\b", head, re.I):
        return None
    # Pure aggregate projections have no meaningful duplicate rows.
    m = re.match(r"^SELECT\s+(.*?)\s+FROM\b", s, re.I | re.S)
    if m and re.search(r"\b(COUNT|SUM|AVG|MIN|MAX|TOTAL|GROUP_CONCAT)\s*\(", m.group(1), re.I):
        return None
    base = _strip_trailing_limit(s)
    if not base:
        return None
    return "SELECT DISTINCT * FROM (\n" + base + "\n)"


def repair_message(sql, res, truncated, dup_info=None):
    lines = ["Your previous draft was:", "```sql", sql, "```"]
    if truncated:
        lines.append("It appears incomplete or malformed (cut off mid-statement). Rewrite it as one short, complete query.")
    if res is None:
        lines.append("It could not be executed.")
    elif not res.get("ok"):
        lines.append(f"Execution FAILED with error: {res.get('error')}")
        lines.append("Fix the syntax or the table/column names (use only names present in the schema).")
    elif res.get("n_rows", 0) == 0:
        lines.append("It executed successfully but returned 0 rows.")
        lines.append(
            "The question almost certainly has a non-empty answer, so a filter value or join is probably wrong. "
            "Common causes: string literals that do not exactly match stored values (case, spacing, abbreviations, "
            "suffixes like 'Bachelors' vs 'Bachelor'), matching the wrong column, case-sensitive joins on text keys, "
            "or an over-restrictive combination of conditions. "
            "If needed, first run a small probe query such as SELECT DISTINCT <column> FROM <table> LIMIT 20 "
            "to see the actual stored values, then write the corrected final query using them."
        )
    else:
        lines.append(f"It returned {res.get('n_rows')} rows; columns: {res.get('columns')}.")
        lines.append("Re-check that it answers the question exactly (right columns, right comparison semantics).")
    if dup_info:
        n_all, n_dist = dup_info
        lines.append(
            f"Duplicate-row check: the draft returns {n_all} rows but only {n_dist} distinct rows. "
            "A one-to-many join is repeating entities. If the question asks for a list of entities, "
            "each should appear once: add DISTINCT, or filter with WHERE EXISTS / IN instead of joining "
            "the one-to-many table into the output. Also re-check that any COUNT/SUM/AVG is not inflated "
            "by the same fan-out (count over the relationship table itself, or de-duplicate first)."
        )
    lines.append(
        "Reply with ONLY the corrected final query in a single ```sql code block. "
        "Keep it minimal: select exactly the columns asked for, nothing extra."
    )
    return "\n".join(lines)


def solve(task, env):
    max_tokens = env.config.get("max_tokens", 800)
    messages = [
        {"role": "system", "content": env.prompt("system_prompt.md")},
        {"role": "user", "content": build_user(task, env)},
    ]
    reply = env.chat(messages, max_tokens=max_tokens)
    sql = extract_sql(reply)

    truncated = looks_truncated(sql)
    res = None
    try:
        res = env.execute(sql, max_rows=20)
    except Exception:
        res = None

    ok = res is not None and res.get("ok")
    n_rows = res.get("n_rows", 0) if ok else 0

    # Local fan-out probe: does the result contain duplicate rows? This catches
    # semantically wrong drafts that execute cleanly (repeated entities from a
    # one-to-many join) without spending a policy call.
    dup_info = None
    if ok and not truncated and n_rows > 1:
        dv = distinct_variant(sql)
        if dv:
            try:
                rd = env.execute(dv, max_rows=20)
            except Exception:
                rd = None
            if rd is not None and rd.get("ok"):
                nd = rd.get("n_rows", 0)
                if nd < n_rows:
                    dup_info = (n_rows, nd)

    need_repair = truncated or not ok or n_rows == 0 or dup_info is not None
    if not need_repair:
        return {"sql": sql}

    messages.append({"role": "assistant", "content": reply})
    messages.append({"role": "user", "content": repair_message(sql, res, truncated, dup_info)})
    try:
        reply2 = env.chat(messages, max_tokens=max_tokens)
    except Exception:
        return {"sql": sql}
    sql2 = extract_sql(reply2)
    if not sql2:
        return {"sql": sql}

    # If the model used the repair turn as a probe query, inspect its output
    # locally (no extra policy call) so the choice below is informed.
    res2 = None
    try:
        res2 = env.execute(sql2, max_rows=20)
    except Exception:
        res2 = None

    def usable(r):
        return r is not None and r.get("ok") and r.get("n_rows", 0) > 0

    if usable(res2) or not usable(res):
        # Prefer the repaired query unless it is unusable and the draft worked.
        if looks_truncated(sql2) and not truncated:
            return {"sql": sql}
        return {"sql": sql2}
    return {"sql": sql}

